input.command:
cd /app/ssl && {
  echo "Subject: $(openssl x509 -in server.crt -noout -subject | sed 's/^subject=//')"
  echo "Not Before: $(openssl x509 -in server.crt -noout -startdate | sed 's/^notBefore=//' | xargs -I{} date -u -d '{}' +%Y-%m-%d)"
  echo "Not After: $(openssl x509 -in server.crt -noout -enddate | sed 's/^notAfter=//' | xargs -I{} date -u -d '{}' +%Y-%m-%d)"
  echo "SHA-256 Fingerprint: $(openssl x509 -in server.crt -noout -fingerprint -sha256 | sed 's/^sha256 Fingerprint=//')"
} > verification.txt && cat verification.txt && openssl x509 -in server.crt -noout -checkend 31536000 >/dev/null; echo "checkend(365d) exit: $?"
